// ---------------------------------------------------------------------------
// Una imagen chiquita, hecha a mano: un cuadrado claro y una diagonal.
// 18x18 pixeles en escala de grises, 0 = negro, 255 = blanco.
// ---------------------------------------------------------------------------
const N = 18;
const imagen = [];
for (let y = 0; y < N; y++) {
  const fila = [];
  for (let x = 0; x < N; x++) {
    let v = 25;                                   // el fondo
    if (x >= 5 && x <= 12 && y >= 5 && y <= 12) v = 205;   // el cuadrado
    if (Math.abs(x - y) <= 0 && x >= 1 && x <= 16) v = 240; // la diagonal
    fila.push(v);
  }
  imagen.push(fila);
}

// ---------------------------------------------------------------------------
// Tres filtros de 3x3. Nueve numeros cada uno. Eso es todo lo que aprende
// una capa convolucional por filtro.
// ---------------------------------------------------------------------------
const FILTROS = [
  { nombre: 'Borde vertical',   k: [[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]] },
  { nombre: 'Borde horizontal', k: [[-1, -2, -1], [0, 0, 0], [1, 2, 1]] },
  { nombre: 'Desenfoque',       k: [[1, 1, 1], [1, 1, 1], [1, 1, 1]].map(f => f.map(v => v / 9)) },
];

// La convolucion, entera. Son ocho lineas.
function convolucionar(img, k) {
  const alto = img.length, ancho = img[0].length, lado = k.length;
  const salida = [];
  for (let y = 0; y + lado <= alto; y++) {
    const fila = [];
    for (let x = 0; x + lado <= ancho; x++) {
      let suma = 0;
      for (let j = 0; j < lado; j++)
        for (let i = 0; i < lado; i++)
          suma += img[y + j][x + i] * k[j][i];
      fila.push(suma);
    }
    salida.push(fila);
  }
  return salida;
}

// Para poder mirarlo: cada numero se dibuja con un caracter segun su fuerza.
const ESCALA = ' .:-=+*#%@';
function dibujar(m) {
  let max = 0;
  for (const f of m) for (const v of f) max = Math.max(max, Math.abs(v));
  if (max === 0) max = 1;
  return m.map(f => f.map(v => {
    const i = Math.round((Math.abs(v) / max) * (ESCALA.length - 1));
    return ESCALA[i] + ESCALA[i];        // doble, para que quede cuadrado
  }).join('')).join('\n');
}

const salida = [];

salida.push({
  paso: '1. La imagen que entra',
  tamanio: N + ' x ' + N + ' = ' + (N * N) + ' numeros',
  dibujo: dibujar(imagen),
});

for (const f of FILTROS) {
  const mapa = convolucionar(imagen, f.k);
  salida.push({
    paso: '2. Filtro: ' + f.nombre,
    nucleo: f.k.map(fila => fila.map(v => v.toFixed(2).padStart(6)).join(' ')).join('\n'),
    pesos_del_filtro: 9,
    tamanio_del_mapa: mapa.length + ' x ' + mapa[0].length,
    dibujo: dibujar(mapa),
  });
}

// ---------------------------------------------------------------------------
// La cuenta de la lamina 11, hecha de verdad.
// ---------------------------------------------------------------------------
const LADO = 224, CANALES = 3, NEURONAS = 1000, FILTROS_CONV = 16;
const entradas = LADO * LADO * CANALES;
const densa = entradas * NEURONAS + NEURONAS;
const conv = (3 * 3 * CANALES + 1) * FILTROS_CONV;

salida.push({
  paso: '3. Por que la convolucion gana',
  imagen_de_referencia: LADO + ' x ' + LADO + ' en color = ' + entradas.toLocaleString('es-AR') + ' numeros de entrada',
  red_densa_primera_capa: densa.toLocaleString('es-AR') + ' parametros (capa oculta de ' + NEURONAS + ' neuronas)',
  capa_convolucional: conv.toLocaleString('es-AR') + ' parametros (' + FILTROS_CONV + ' filtros de 3x3)',
  la_densa_usa: Math.round(densa / conv).toLocaleString('es-AR') + ' veces mas parametros',
  tamanio_de_salida: 'formula: (32 - 3 + 0) / 1 + 1 = 30, o sea 30 x 30 x ' + FILTROS_CONV,
});

return salida.map(json => ({ json }));
